package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.SerializerProvider;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DateTimeSerializerBase._asTimestamp
 */
public class DateTimeSerializerBase__asTimestamp_TriageGen2Test {

    // Concrete implementation of the abstract class for testing purposes
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<Date> {

        protected TestDateTimeSerializer(Class<Date> type, Boolean useTimestamp, java.text.DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
        }

        @Override
        public void serialize(Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) throws java.io.IOException {
            // Not used in _asTimestamp tests
        }

        @Override
        protected long _timestamp(Date value) {
            return value == null ? 0L : value.getTime();
        }

        @Override
        public com.fasterxml.jackson.databind.JsonSerializer<?> createContextual(SerializerProvider serializers, com.fasterxml.jackson.databind.ser.BeanProperty property) {
            return this;
        }

        @Override
        public com.fasterxml.jackson.databind.JsonNode getSchema(SerializerProvider serializers, com.fasterxml.jackson.databind.JavaType typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) {
            // Not used
        }

        @Override
        protected void _acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint, boolean asNumber) {
            // Not used
        }
    }

    @Test
    public void testAsTimestamp_WhenUseTimestampIsNotNull() {
        // Case 1: _useTimestamp is true
        TestDateTimeSerializer serializerTrue = new TestDateTimeSerializer(Date.class, true, null);
        assertTrue("Should return true when _useTimestamp is true", serializerTrue._asTimestamp(null));

        // Case 2: _useTimestamp is false
        TestDateTimeSerializer serializerFalse = new TestDateTimeSerializer(Date.class, false, null);
        assertFalse("Should return false when _useTimestamp is false", serializerFalse._asTimestamp(null));
    }

    @Test
    public void testAsTimestamp_WhenCustomFormatIsNullAndProviderIsEnabled() {
        SerializerProvider serializers = mock(SerializerProvider.class);
        when(serializers.isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)).thenReturn(true);

        // Case 3: _useTimestamp is null, _customFormat is null, feature enabled
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);
        assertTrue("Should return true when feature is enabled in provider", serializer._asTimestamp(serializers));

        // Case 4: _useTimestamp is null, _customFormat is null, feature disabled
        when(serializers.isEnabled(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)).thenReturn(false);
        assertFalse("Should return false when feature is disabled in provider", serializer._asTimestamp(serializers));
    }

    @Test
    public void testAsTimestamp_WhenCustomFormatIsNullAndProviderIsNull_ThrowsException() {
        // Case 5: _useTimestamp is null, _customFormat is null, serializers is null -> Expect IllegalArgumentException
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, null);
        try {
            serializer._asTimestamp(null);
            fail("Expected IllegalArgumentException to be thrown");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Null SerializerProvider passed"));
        }
    }

    @Test
    public void testAsTimestamp_WhenCustomFormatIsNotNull() {
        SerializerProvider serializers = mock(SerializerProvider.class);
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");

        // Case 6: _useTimestamp is null, _customFormat is NOT null -> Should return false
        TestDateTimeSerializer serializer = new TestDateTimeSerializer(Date.class, null, sdf);
        assertFalse("Should return false when a custom format is provided", serializer._asTimestamp(serializers));
    }
}
